    }

    bool isOutOfBounds(Coordinate coordinate) const
    {
        return coordinate.X < 0 || coordinate.X >= _width || coordinate.Y < 0 || coordinate.Y >= _height;
    }

    int move(string direction) 
    {
        _snake.Move(direction);

        if (_snake.AteSelf())
            return -1;

        auto snakeHead = _snake.Head();
